#include <vector>
using namespace std;

int main() {
    int input;
    cin >> input;

    if (input < 6) {
        cout << 0;
        return 0;
    }

    vector<int> primeFactorCount(input + 1, 0);

    for (int i = 2; i <= input; ++i) {
        if (primeFactorCount[i] == 0) {
            for (int j = i; j <= input; j += i) {
                ++primeFactorCount[j];
            }
        }
    }

    int answer = 0;
    for (int i = 6; i <= input; ++i) {
        if (primeFactorCount[i] == 2) {
            ++answer;
        }
    }

    cout << answer;
    return 0;
}

#include <stdio.h>

#define MAX 3000

int main(void)
{
    int input;
    int prime[450];
    int isComposite[MAX + 1] = {0};
    int primeCount = 0;
    int answer = 0;

    for (int i = 2; i <= MAX; ++i) {
        if (!isComposite[i]) {
            prime[primeCount++] = i;

            for (int j = i * 2; j <= MAX; j += i) {
                isComposite[j] = 1;
            }
        }
    }

    scanf("%d", &input);

    for (int value = 6; value <= input; ++value) {
        int count = 0;

        for (int i = 0; i < primeCount && prime[i] <= value; ++i) {
            if (value % prime[i] == 0) {
                ++count;
            }
        }

        if (count == 2) {
            ++answer;
        }
    }

    printf("%d", answer);
    return 0;
}

